const item = $input.first().json;
const trust = item?.report?.categories?.trust;
const security = item?.report?.categories?.security;
const checks = item?.report?.checks;
if (item?.report?.schemaVersion !== '2.0' || !Number.isInteger(trust?.score) || !Number.isInteger(security?.score) || !Array.isArray(checks)) {
  throw new Error('invalid-trust-stage-input');
}
if ([trust.score, security.score].some(score => score < 0 || score > 100) || checks.length > 120) {
  throw new Error('invalid-trust-score');
}
const sensitiveKeys = new Set(['html', 'rawhtml', 'body', 'headers', 'authorization', 'proxyauthorization', 'apikey', 'password', 'secret', 'token', 'cookie', 'setcookie']);
const pending = [item.report];
while (pending.length) {
  const value = pending.pop();
  if (!value || typeof value !== 'object') continue;
  for (const [key, nested] of Object.entries(value)) {
    const normalizedKey = key.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (sensitiveKeys.has(normalizedKey)) throw new Error('sensitive-data-in-report');
    if (nested && typeof nested === 'object') pending.push(nested);
  }
}
item.auditStages = [...(item.auditStages || []), 'trust-security'];
return [{ json: item }];
